// Hand-drawn die-cut sticker characters.
//
// These deliberately sit OUTSIDE the theme token system — the colours are
// hard-coded so the stickers stay exactly as warm and colourful in light mode
// as in dark. They are the one place in the app that breaks the design system
// on purpose: they should feel drawn by a person and stuck onto the timeline,
// not generated by it.
//
// Every character takes `hovered` and nudges one or two of its own details in
// response, so the reaction feels characterful rather than a generic scale-up.

const CREAM = '#FFF8EE'
const BLUSH = '#F58FA8'

// shared: thick cream underlay = the die-cut edge, drawn beneath the fill
function DieCut({ d, fill, ink, strokeWidth = 2.6 }) {
  return (
    <>
      <path d={d} fill={CREAM} stroke={CREAM} strokeWidth="9" strokeLinejoin="round" />
      <path d={d} fill={fill} stroke={ink} strokeWidth={strokeWidth} strokeLinejoin="round" />
    </>
  )
}

const ease = 'transform .45s cubic-bezier(0.34, 1.56, 0.64, 1)'

