      <g transform="rotate(-7 36 34)">
        <DieCut d={body} fill="#B9A7F0" ink="#2E2A33" />
        <ellipse cx="22" cy="38" rx="5" ry="3.2" fill={BLUSH} opacity=".6" />
        <ellipse cx="49" cy="38" rx="5" ry="3.2" fill={BLUSH} opacity=".6" />
        <path d="M21 31q4.5 5 9 0" fill="none" stroke="#2E2A33" strokeWidth="2.6" strokeLinecap="round" />
        <path d="M41 31q4.5 5 9 0" fill="none" stroke="#2E2A33" strokeWidth="2.6" strokeLinecap="round" />
        <path d="M32 40q4 3.5 8 0" fill="none" stroke="#2E2A33" strokeWidth="2.4" strokeLinecap="round" />
      </g>
      {/* the z's drift up when you look at it */}
      <g style={{ transform: hovered ? 'translate(2px,-5px)' : 'none', transition: ease }}>
        <path d="M60 20h7l-7 8h7" fill="none" stroke="#B9A7F0" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round" />
        <path d="M64 7h5l-5 6h5" fill="none" stroke="#B9A7F0" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" opacity=".65" />
      </g>
